class BaseNet(torch.nn.Module):

    def __init__(self, n_inputs, n_outputs, n_tasks, args):
        super(BaseNet, self).__init__()
        self.args = args
        nl, nh = args.n_layers, args.n_hiddens
        config = ModelFactory.get_model(model_type = args.arch, sizes = [n_inputs] + [nh] * nl + [n_outputs],
                                                dataset = args.dataset, args=args)

        self.net = Learner(config, args)
        self.net.define_task_lr_params(alpha_init = args.alpha_init)

        self.opt_wt = torch.optim.SGD(list(self.net.parameters()), lr=args.opt_wt)
        self.opt_lr = torch.optim.SGD(list(self.net.alpha_lr.parameters()), lr=args.opt_lr)

        self.epoch = 0
        self.M = []; self.M_new = []; self.age = 0

        self.loss = torch.nn.CrossEntropyLoss()
        self.is_cifar = ((args.dataset == 'cifar100') or (args.dataset == 'tinyimagenet'))
        self.glances = args.glances; self.pass_itr = 0; self.real_epoch = 0

        self.current_task = 0
        self.memories = args.memories
        self.batchSize = int(args.replay_batch_size)

        self.cuda = args.cuda
        if self.cuda: self.net = self.net.cuda()
        self.n_outputs = n_outputs

    def push_to_mem(self, batch_x, batch_y, t):
        if(self.real_epoch > 0 or self.pass_itr>0): return
        batch_x = batch_x.cpu(); batch_y = batch_y.cpu(); t = t.cpu()

        for i in range(batch_x.shape[0]):
            self.age += 1
            if len(self.M_new) < self.memories: self.M_new.append([batch_x[i], batch_y[i], t])
            else:
                p = random.randint(0,self.age)
                if p < self.memories: self.M_new[p] = [batch_x[i], batch_y[i], t]


    def getBatch(self, x, y, t, batch_size=None):
        mxi = np.array(x) if x is not None else np.empty( shape=(0, 0) )
        myi = np.array(y) if y is not None else np.empty( shape=(0, 0) )
        mti = np.ones(x.shape[0], dtype=int)*t if x is not None else np.empty( shape=(0, 0) )

        bxs = []; bys = []; bts = []

        MEM = self.M if self.args.use_old_task_memory and t>0 else self.M_new
        batch_size = self.batchSize if batch_size is None else batch_size

        if len(MEM) > 0:
            order = [i for i in range(0,len(MEM))]
            osize = min(batch_size,len(MEM))
            for j in range(0,osize):
                shuffle(order)
                k = order[j]
                x_mem,y_mem,t_mem = MEM[k]

                bxs.append(np.array(x_mem)); bys.append(np.array(y_mem)); bts.append(np.array(t_mem))

        for j in range(len(myi)): bxs.append(mxi[j]); bys.append(myi[j]); bts.append(mti[j])

        bxs = Variable(torch.from_numpy(np.array(bxs))).float()
        bys = Variable(torch.from_numpy(np.array(bys))).long().view(-1)
        bts = Variable(torch.from_numpy(np.array(bts))).long().view(-1)

        if self.cuda: bxs = bxs.cuda(); bys = bys.cuda(); bts = bts.cuda()
        return bxs,bys,bts

    def compute_offsets(self, task):
        offset1 = task * self.nc_per_task; offset2 = (task + 1) * self.nc_per_task
        return int(offset1), int(offset2)

    def zero_grads(self):
        if self.args.learn_lr: self.opt_lr.zero_grad()
        self.opt_wt.zero_grad(); self.net.zero_grad(); self.net.alpha_lr.zero_grad()


